sparql:
SELECT DISTINCT ?p ?artist WHERE {
  ?p rdfs:label ?artist .
  ?a mc:artist ?p ; mc:dataset "paintings-1850-1900" ; mc:museum "rijksmuseum" .
  ?b mc:artist ?p ; mc:dataset "paintings-1850-1900" ; mc:museum "met" .
  ?c mc:artist ?p ; mc:dataset "paintings-1850-1900" ; mc:museum "aic" .
} ORDER BY ?artist

SELECT DISTINCT ?w ?title WHERE {
  ?w mc:museum "rijksmuseum" ; dcterms:title ?title .
  { ?w mc:subject ?c } UNION { ?w mc:aiSubject ?c }
  ?c skos:prefLabel|skos:altLabel ?l .
  FILTER(CONTAINS(LCASE(STR(?l)), "landscape"))
}

SELECT DISTINCT ?w ?title WHERE {
  ?w mc:dataset "paintings-1850-1900" ; dcterms:title ?title .
  { ?w mc:style ?s } UNION { ?w mc:inferredStyle ?s }
  ?s skos:prefLabel ?sl . FILTER(LCASE(STR(?sl)) = "impressionism")
  { ?w mc:subject ?c } UNION { ?w mc:aiSubject ?c }
  ?c skos:prefLabel|skos:altLabel ?l . FILTER(LCASE(STR(?l)) = "snow")
}

SELECT (COUNT(DISTINCT ?w) AS ?n) WHERE {
  ?w mc:dataset "paintings-1850-1900" ; mc:aiSubject ?c .
  FILTER NOT EXISTS { ?w mc:subject ?c }
}

SELECT DISTINCT ?w ?title WHERE {
  ?w mc:dataset "paintings-1850-1900" ; dcterms:title ?title ; mc:aiSubject ?c .
  ?c skos:prefLabel|skos:altLabel ?l . FILTER(LCASE(STR(?l)) = "night")
  FILTER NOT EXISTS {
    ?w mc:subject ?m .
    ?m skos:prefLabel|skos:altLabel ?ml . FILTER(LCASE(STR(?ml)) = "night")
  }
}

SELECT DISTINCT ?p ?artist WHERE {
  ?w a mc:Work ; mc:artist ?p .
  ?p rdfs:label ?artist ; mc:movement ?m .
  ?m skos:prefLabel|skos:altLabel ?l . FILTER(LCASE(STR(?l)) = "hague school")
} ORDER BY ?artist

SELECT ?artist ?name (COUNT(DISTINCT ?w) AS ?paintings) WHERE {
  ?w mc:dataset "paintings-1850-1900" ; mc:artist ?artist .
  ?artist rdfs:label ?name .
} GROUP BY ?artist ?name ORDER BY DESC(?paintings) LIMIT 5

SELECT DISTINCT ?w ?title ?year WHERE {
  ?w mc:dataset "paintings-1850-1900" ; dcterms:title ?title ; mc:beginYear ?year .
  FILTER(?year < 1870)
  { ?w mc:subject ?c } UNION { ?w mc:aiSubject ?c }
  ?c skos:prefLabel|skos:altLabel ?l .
  FILTER(LCASE(STR(?l)) IN ("boat", "boats"))
} ORDER BY ?year

SELECT DISTINCT ?w ?title ?attribution ?museum WHERE {
  ?w mc:qualifiedArtist ?p ; dcterms:title ?title ; mc:museum ?museum .
  ?p rdfs:label ?attribution .
  FILTER(CONTAINS(LCASE(?attribution), "van gogh"))
} ORDER BY ?attribution ?title

SELECT DISTINCT ?w ?title WHERE {
  ?w mc:museum "met" ; dcterms:title ?title .
  { ?w mc:subject ?c1 } UNION { ?w mc:aiSubject ?c1 }
  ?c1 skos:prefLabel|skos:altLabel ?l1 .
  FILTER(CONTAINS(LCASE(STR(?l1)), "portrait"))
  { ?w mc:subject ?c2 } UNION { ?w mc:aiSubject ?c2 }
  ?c2 skos:prefLabel|skos:altLabel ?l2 .
  FILTER(CONTAINS(LCASE(STR(?l2)), "woman") || CONTAINS(LCASE(STR(?l2)), "women") || LCASE(STR(?l2)) IN ("female", "girl", "girls"))
}

SELECT ?artist (COUNT(DISTINCT ?museum) AS ?museums) (GROUP_CONCAT(DISTINCT ?museum; separator=", ") AS ?museumList) WHERE {
  ?p mc:movement ?m ; rdfs:label ?artist .
  ?m skos:prefLabel ?ml . FILTER(LCASE(STR(?ml)) = "impressionism")
  ?w a mc:Work ; mc:artist ?p ; mc:museum ?museum .
} GROUP BY ?artist HAVING(COUNT(DISTINCT ?museum) > 1) ORDER BY DESC(?museums) ?artist
